function nav(){return NAV.map(g=>[g[0],g[1].filter(i=>allowed(i[0]))]).filter(g=>g[1].length)}
function data(cfg){return cfg?(state.db[cfg.key]||[]):[]}
function statuses(rows){return [...new Set(rows.map(r=>r.status||r.approvalStage||r.costStatus||r.readiness).filter(Boolean))]}
function value(v,key,cfg){if(cfg&&cfg.money.includes(key))return `<strong>${fmtMoney(v)}</strong>`;if(v===null||v===undefined||v==='')return '—';if(Array.isArray(v))return v.map(x=>typeof x==='object'?esc(x.name||x.sku||JSON.stringify(x)):esc(x)).join(', ');if(typeof v==='object')return esc(JSON.stringify(v));const s=String(v),l=s.toLowerCase();if(['active','approved','released','completed','closed','pass','ready','healthy','success'].some(x=>l===x.toLowerCase()))return `<span class="status status-active">${esc(s)}</span>`;if(['draft','review','pending','plant trial','technical review','qa review','cost review','conditional','queued','saved'].some(x=>l.includes(x)))return `<span class="status status-draft">${esc(s)}</span>`;if(['failed','blocked','rejected','expired','superseded','shortage'].some(x=>l.includes(x)))return `<span class="status status-inactive">${esc(s)}</span>`;if(/date$/i.test(key)||['createdAt','updatedAt','timestamp','runDate','effectiveDate','validFrom','validTo'].includes(key))return fmtDate(v);return esc(s)}
function audit(action,entity,before='—',after='—'){const a=state.db.auditLogs||(state.db.auditLogs=[]);a.unshift({id:Date.now(),number:'AUD-'+String(a.length+1).padStart(4,'0'),actor:state.session.name,action,entity,before,after,timestamp:new Date().toLocaleString('en-IN'),ip:'Demo Browser',status:'Success',createdAt:now(),updatedAt:now()})}
function toast(msg,type='success'){const root=byId('toast-root');if(!root)return;const n=document.createElement('div');n.className='toast '+type;n.innerHTML=`<strong>${type==='error'?'Attention':'Done'}</strong><span>${esc(msg)}</span>`;root.appendChild(n);setTimeout(()=>n.remove(),3500)}
function initials(n){return String(n||'T90').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}
function shell(content){document.documentElement.dataset.theme=state.ui.theme;const side=nav().map(g=>`<div class="nav-section"><div class="nav-title">${esc(g[0])}</div>${g[1].map(i=>`<a class="nav-item ${state.route===i[0]?'active':''}" href="#/${i[0]}"><span class="nav-icon">${i[1]}</span><span class="nav-label">${esc(i[2])}</span>${i[0]==='approvals'&&pendingApprovals()?`<span class="nav-badge">${pendingApprovals()}</span>`:''}</a>`).join('')}</div>`).join('');byId('app').innerHTML=`<div class="shell ${state.ui.sidebar?'sidebar-open':''}"><aside class="sidebar"><div class="sidebar-brand"><div class="logo-mark">T90</div><div class="brand-copy"><strong>Tan90 ERP</strong><span>BOM, Recipe & Costing</span></div><button class="icon-btn mobile-menu" data-action="close-sidebar">×</button></div><div class="sidebar-scroll">${side}</div><div class="sidebar-user"><div class="avatar">${initials(state.session.name)}</div><div><strong>${esc(state.session.name)}</strong><span>${esc(title(state.session.role))}</span></div><button class="icon-btn" data-action="logout">↗</button></div></aside><div class="mobile-overlay" data-action="close-sidebar"></div><main class="main-shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="open-sidebar">☰</button><button class="search-launch" data-action="command"><span>⌕ Search BOM, recipes, costs...</span><kbd>Ctrl K</kbd></button><div class="top-actions"><button class="icon-btn" data-action="theme">◐</button><button class="icon-btn" data-action="notifications">🔔<span class="notification-dot"></span></button><div class="top-user"><div class="avatar">${initials(state.session.name)}</div></div></div></header><section class="content">${content}</section></main><nav class="mobile-bottom-nav"><a href="#/dashboard">Home</a><a href="#/recipes">Recipes</a><a href="#/bom-headers">BOMs</a><a href="#/cost-sheets">Costs</a></nav></div>${state.command?commandHtml():''}${state.modal?modalHtml():''}`;bind()}
function head(eyebrow,h,desc,actions=''){return `<div class="page-head"><div><p class="eyebrow">${esc(eyebrow)}</p><h1 class="page-title">${esc(h)}</h1><p>${esc(desc)}</p></div><div class="page-actions">${actions}</div></div>`}
function kpi(l,v,s,i='•'){return `<div class="kpi-card"><div class="kpi-top"><span>${esc(i)}</span><span class="kpi-trend">${esc(s)}</span></div><div class="kpi-value">${v}</div><div class="kpi-label">${esc(l)}</div></div>`}
function progress(p){return `<div class="progress"><span style="width:${Math.max(0,Math.min(100,Number(p)||0))}%"></span></div>`}
function pendingApprovals(){return (state.db.approvals||[]).filter(x=>x.status==='Pending').length}
function sum(key,field){return (state.db[key]||[]).reduce((a,r)=>a+Number(r[field]||0),0)}
function dashboard(){const released=(state.db.boms||[]).filter(x=>String(x.status).toLowerCase()==='released').length, recipes=(state.db.recipes||[]).length, pending=pendingApprovals(), avgMargin=(state.db.finishedGoods||[]).reduce((a,x)=>a+Number(x.marginPct||0),0)/Math.max(1,(state.db.finishedGoods||[]).length);const stages=[['Formula',state.db.recipes.length,'recipes'],['Technical',state.db.engineeringChangeOrders.filter(x=>x.approvalStage==='Technical Review').length,'engineering-change-orders'],['QA',state.db.approvals.filter(x=>x.currentApprover==='QA Manager').length,'approvals'],['Cost',state.db.costSheets.length,'cost-sheets'],['Plant Trial',state.db.recipes.filter(x=>x.status==='Plant Trial').length,'recipes'],['Released',released,'bom-headers'],['MRP Ready',state.db.mrpReadiness.filter(x=>x.readiness==='Ready').length,'mrp-readiness']];return head('BOM, Recipe & Costing','Product Structure Command Center','Control formulations, BOM revisions, routing, cost roll-up and release readiness.',`<a class="btn btn-primary" href="#/recipes">+ New recipe</a><a class="btn btn-secondary" href="#/cost-rollups">Run cost roll-up</a>`)+`<div class="kpi-grid">${kpi('Active recipes',recipes,'Controlled versions','RC')}${kpi('Released BOMs',released,'Production usable','BH')}${kpi('Pending approvals',pending,'Across gates','AP')}${kpi('Average margin',fmtNum(avgMargin,1)+'%','Current product mix','MG')}${kpi('Standard cost value',fmtMoney(sum('standardCosts','total')),'Current standards','₹')}</div><section class="card"><div class="card-head"><div><h2>Design-to-release flow</h2><p>Every product structure passes technical, quality, costing and plant gates.</p></div></div><div class="flow-ribbon">${stages.map((s,i)=>`<a href="#/${s[2]}" class="flow-node"><strong>${s[1]}</strong><span>${s[0]}</span></a>${i<stages.length-1?'<span class="flow-arrow">→</span>':''}`).join('')}</div></section><div class="grid grid-2"><section class="card"><div class="card-head"><div><h2>Approval inbox</h2><p>Release decisions approaching SLA.</p></div><a href="#/approvals">View all</a></div><div class="card-body compact-list">${state.db.approvals.slice(0,5).map(x=>mini(x.reference,x.title,x.currentApprover,x.status,'approvals',x.id)).join('')}</div></section><section class="card"><div class="card-head"><div><h2>Cost & margin watch</h2><p>Products with cost movement or margin gap.</p></div><a href="#/margin-analysis">View analysis</a></div><div class="card-body">${state.db.finishedGoods.map(x=>`<div class="metric-block"><div><span>${esc(x.name)}</span><strong>${fmtNum(x.marginPct,1)}%</strong></div>${progress(x.marginPct)}</div>`).join('')}</div></section></div><div class="grid grid-2"><section class="card"><div class="card-head"><div><h2>Recent recipe versions</h2></div><a href="#/recipe-versions">View all</a></div><div class="card-body compact-list">${state.db.recipeVersions.slice(0,5).map(x=>mini(x.recipe,x.changeSummary,x.approvalStage,x.status,'recipe-versions',x.id)).join('')}</div></section><section class="card"><div class="card-head"><div><h2>MRP readiness</h2></div><a href="#/mrp-readiness">Open readiness</a></div><div class="card-body">${state.db.mrpReadiness.slice(0,5).map(x=>`<div class="cycle-row"><div><strong>${esc(x.product)}</strong><span>${esc(x.readiness)} · ${x.blockers} blocker(s)</span></div>${progress(x.materialCoveragePct)}<span class="status ${x.readiness==='Ready'?'status-active':'status-draft'}">${x.materialCoveragePct}%</span></div>`).join('')}</div></section></div>`}
function mini(a,b,c,d,r,id){return `<a class="mini-row" href="#/${r}/${id}"><div><strong>${esc(a)}</strong><span>${esc(b)}</span></div><div><strong>${esc(c)}</strong><span>${value(d,'status')}</span></div></a>`}
function myTasks(){const t=[];(state.db.approvals||[]).filter(x=>x.status==='Pending').forEach(x=>t.push({id:x.id,kind:'Approval',ref:x.reference,title:x.title,owner:x.currentApprover,due:x.dueDate,route:'approvals'}));(state.db.engineeringChangeOrders||[]).filter(x=>['Draft','Review'].includes(x.status)).forEach(x=>t.push({id:x.id,kind:'Change order',ref:x.number,title:x.title,owner:x.approvalStage,due:x.effectiveDate,route:'engineering-change-orders'}));return head('Personal Workspace','My Tasks','One queue for formulation, costing, QA and release actions.')+`<section class="card"><div class="card-head"><h2>${t.length} active tasks</h2><span class="chip">${esc(title(state.session.role))}</span></div><div class="card-body task-grid">${t.map(x=>`<a class="task-card" href="#/${x.route}/${x.id}"><div class="task-kind">${esc(x.kind)}</div><h3>${esc(x.ref)}</h3><p>${esc(x.title)}</p><div><span class="status status-draft">Action</span><small>${esc(x.owner)} · ${fmtDate(x.due)}</small></div></a>`).join('')}</div></section>`}
function approvals(){return head('Governance','Approval Inbox','Technical, QA, cost and plant release decisions.',can('approve')?'<button class="btn btn-primary" data-action="approve-selected">Approve selected</button>':'')+listPage({route:'approvals',key:'approvals',title:'Approvals',description:'',columns:['reference','type','title','currentApprover','dueDate','risk','status'],primary:'reference',money:[],readonly:true,workflow:'approval',create:false},true)}
function batchCalculator(){const recipes=state.db.recipes||[],r=recipes.find(x=>x.components&&x.components.length)||recipes[0];const size=Number(window.__batchSize||r.batchSize||500),factor=size/Number(r.batchSize||1);return head('Formulation Tools','Batch Sizing Calculator','Scale an approved recipe while preserving component ratio and loss factors.',`<a class="btn btn-secondary" href="#/batch-sizing">Approved sizes</a>`)+`<section class="card"><div class="card-head"><div><h2>${esc(r.code)} · ${esc(r.product)}</h2><p>Base batch ${r.batchSize} ${r.batchUom}</p></div><label class="field-inline">Target batch <input id="batch-target" type="number" min="1" value="${size}"></label></div><div class="kpi-grid compact">${kpi('Scale factor',fmtNum(factor,3),'Target ÷ base','×')}${kpi('Expected yield',fmtNum(r.yieldPct,1)+'%','Approved assumption','YL')}${kpi('Material cost',fmtMoney(r.materialCost*factor),'Scaled estimate','₹')}</div><div class="table-wrap"><table><thead><tr><th>SKU</th><th>Component</th><th>Base Qty</th><th>Scaled Qty</th><th>UOM</th><th>Wastage</th><th>Scaled Cost</th></tr></thead><tbody>${(r.components||[]).map(l=>`<tr><td class="code">${esc(l.sku)}</td><td>${esc(l.name)}</td><td>${fmtNum(l.qty)}</td><td><strong>${fmtNum(l.qty*factor,3)}</strong></td><td>${esc(l.uom)}</td><td>${fmtNum(l.wastagePct)}%</td><td>${fmtMoney(l.qty*factor*l.unitCost)}</td></tr>`).join('')}</tbody></table></div></section>`}
function versionCompare(){const a=state.db.recipes.find(x=>x.code==='REC-PCM500-R03')||state.db.recipes[1],b=state.db.recipes.find(x=>x.code==='REC-PCM500-R04')||state.db.recipes[0];const map={};(a.components||[]).forEach(x=>map[x.sku]={sku:x.sku,name:x.name,a:x.qty,b:0,uom:x.uom});(b.components||[]).forEach(x=>{map[x.sku]=map[x.sku]||{sku:x.sku,name:x.name,a:0,uom:x.uom};map[x.sku].b=x.qty});return head('Change Control','Version Comparison','Compare component quantities, cost and yield before release.')+`<div class="grid grid-2"><section class="card"><div class="card-head"><h2>${esc(a.code)}</h2><span class="status status-inactive">${esc(a.status)}</span></div><div class="card-body">${metric('Batch size',a.batchSize+' '+a.batchUom)}${metric('Yield',a.yieldPct+'%')}${metric('Material cost',fmtMoney(a.materialCost))}</div></section><section class="card"><div class="card-head"><h2>${esc(b.code)}</h2><span class="status status-active">${esc(b.status)}</span></div><div class="card-body">${metric('Batch size',b.batchSize+' '+b.batchUom)}${metric('Yield',b.yieldPct+'%')}${metric('Material cost',fmtMoney(b.materialCost))}</div></section></div><section class="card"><div class="table-wrap"><table><thead><tr><th>SKU</th><th>Component</th><th>${esc(a.version)}</th><th>${esc(b.version)}</th><th>Delta</th><th>UOM</th></tr></thead><tbody>${Object.values(map).map(x=>`<tr><td class="code">${esc(x.sku)}</td><td>${esc(x.name)}</td><td>${fmtNum(x.a)}</td><td>${fmtNum(x.b)}</td><td><strong>${fmtNum(x.b-x.a)}</strong></td><td>${esc(x.uom)}</td></tr>`).join('')}</tbody></table></div></section>`}
function whereUsed(){const c=state.db.components[0];const uses=[];state.db.recipes.forEach(r=>(r.components||[]).forEach(l=>{if(l.sku===c.code)uses.push({type:'Recipe',code:r.code,name:r.product,qty:l.qty,uom:l.uom,status:r.status})}));state.db.boms.forEach(b=>(b.lines||[]).forEach(l=>{if(l.sku===c.code)uses.push({type:'BOM',code:b.number,name:b.product,qty:l.qty,uom:l.uom,status:b.status})}));return head('Impact Analysis','Where Used','Trace a component across recipes, BOMs and released products.')+`<section class="card"><div class="card-head"><div><h2>${esc(c.code)} · ${esc(c.name)}</h2><p>${uses.length} direct usages found</p></div><select id="where-component">${state.db.components.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.code+' · '+x.name)}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Type</th><th>Object</th><th>Product</th><th>Qty</th><th>UOM</th><th>Status</th></tr></thead><tbody>${uses.map(x=>`<tr><td>${x.type}</td><td class="code">${x.code}</td><td>${x.name}</td><td>${x.qty}</td><td>${x.uom}</td><td>${value(x.status,'status')}</td></tr>`).join('')||'<tr><td colspan="6">No usage found.</td></tr>'}</tbody></table></div></section>`}
function costRollupTool(){const b=state.db.boms[0],r=state.db.recipes[0],mat=(r.components||[]).reduce((a,x)=>a+x.qty*x.unitCost*(1+x.wastagePct/100),0),pack=(b.lines||[]).filter(x=>x.sku!=='REC-PCM500-R04').reduce((a,x)=>a+Number(x.cost||0),0),labor=3422,machine=5680,utility=1240,overhead=(mat+pack+labor+machine+utility)*.085,total=mat+pack+labor+machine+utility+overhead,unit=total/b.baseQty;return head('Costing Engine','Interactive Cost Roll-up','Recalculate recipe, packaging, routing and overhead into a product unit cost.',can('cost')?'<button class="btn btn-primary" data-action="run-rollup">Run & save roll-up</button>':'')+`<div class="kpi-grid">${kpi('Material',fmtMoney(mat),'Recipe + wastage','RM')}${kpi('Packaging',fmtMoney(pack),'BOM packaging lines','PK')}${kpi('Conversion',fmtMoney(labor+machine+utility),'Labor + machine + utility','CV')}${kpi('Overhead',fmtMoney(overhead),'Configured allocation','OH')}${kpi('Unit cost',fmtMoney(unit),'Per finished unit','₹')}</div><section class="card"><div class="card-head"><div><h2>${esc(b.product)}</h2><p>${esc(b.number)} + ${esc(r.code)}</p></div><span class="chip">Batch ${b.baseQty} ${b.uom}</span></div><div class="card-body">${costBar('Recipe material',mat,total)}${costBar('Packaging',pack,total)}${costBar('Labor',labor,total)}${costBar('Machine',machine,total)}${costBar('Utility',utility,total)}${costBar('Overhead',overhead,total)}</div><div class="card-foot"><strong>Total batch cost ${fmtMoney(total)}</strong><strong>Unit cost ${fmtMoney(unit)}</strong></div></section>`}
function costBar(l,v,t){return `<div class="bar-row"><div class="bar-label"><span>${esc(l)}</span><strong>${fmtMoney(v)}</strong></div>${progress(v/t*100)}</div>`}
function metric(l,v){return `<div class="detail-row"><span>${esc(l)}</span><strong>${v}</strong></div>`}
function reports(){const cards=[['BOM Register','Versions, status, effective dates and cost','bom-headers'],['Recipe Yield Report','Formula output, process loss and recovery','yield-loss'],['BOM Cost Report','Component and conversion cost roll-up','cost-sheets'],['Component Where-used','Product impact and phase-out analysis','where-used'],['Cost Variance','Standard vs actual cost drivers','variance-analysis'],['Margin Analysis','Unit economics and target gap','margin-analysis'],['MRP Readiness','Master data blockers before planning','mrp-readiness'],['Audit Trail','Every revision, approval and release','audit-trail']];return head('Analytics','Reports Library','Decision-ready product structure and costing reports.')+`<div class="module-grid">${cards.map(c=>`<a class="module-card" href="#/${c[2]}"><div class="nav-icon">${c[0].split(/\s/).map(x=>x[0]).join('').slice(0,2)}</div><h3>${c[0]}</h3><p>${c[1]}</p><span>Open report →</span></a>`).join('')}</div>`}
function listPage(cfg,embedded=false){let rows=data(cfg);if(state.search){const q=state.search.toLowerCase();rows=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q))}if(state.status!=='all')rows=rows.filter(r=>String(r.status||r.approvalStage||r.costStatus||r.readiness)===state.status);if(state.sort)rows.sort((a,b)=>String(a[state.sort]??'').localeCompare(String(b[state.sort]??''),undefined,{numeric:true})*(state.dir==='asc'?1:-1));const count=rows.length,pages=Math.max(1,Math.ceil(count/state.ui.pageSize));state.page=Math.min(state.page,pages);const slice=rows.slice((state.page-1)*state.ui.pageSize,state.page*state.ui.pageSize);const actions=`${cfg.create&&can('create')&&!cfg.readonly?`<button class="btn btn-primary" data-action="new">+ New ${esc(cfg.title.replace(/s$/,''))}</button>`:''}<button class="btn btn-secondary" data-action="export-current">Export CSV</button>`;const body=`<section class="card"><div class="list-toolbar"><label class="list-search">⌕<input id="list-search" value="${esc(state.search)}" placeholder="Search ${esc(cfg.title.toLowerCase())}"></label><select id="status-filter"><option value="all">All statuses</option>${statuses(rows).map(s=>`<option ${state.status===s?'selected':''}>${esc(s)}</option>`).join('')}</select><span class="chip">${count} records</span></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" data-action="select-all"></th>${cfg.columns.map(c=>`<th><button class="sort-btn" data-sort="${c}">${esc(title(c))}${state.sort===c?(state.dir==='asc'?' ↑':' ↓'):''}</button></th>`).join('')}<th>Actions</th></tr></thead><tbody>${slice.length?slice.map(r=>row(cfg,r)).join(''):`<tr><td colspan="${cfg.columns.length+2}"><div class="empty-state"><h3>No records found</h3><p>Adjust filters or create a new record.</p></div></td></tr>`}</tbody></table></div><div class="mobile-card-list">${slice.map(r=>mobile(cfg,r)).join('')}</div><div class="card-foot"><span>Showing ${count?((state.page-1)*state.ui.pageSize+1):0}–${Math.min(state.page*state.ui.pageSize,count)} of ${count}</span><div class="pagination"><button class="page-btn" data-page="${state.page-1}" ${state.page===1?'disabled':''}>‹</button>${Array.from({length:pages},(_,i)=>`<button class="page-btn ${state.page===i+1?'active':''}" data-page="${i+1}">${i+1}</button>`).join('')}<button class="page-btn" data-page="${state.page+1}" ${state.page===pages?'disabled':''}>›</button></div></div></section>`;return embedded?body:head('BOM, Recipe & Costing',cfg.title,cfg.description,actions)+body}
function row(cfg,r){return `<tr class="record-row" data-open="${r.id}"><td onclick="event.stopPropagation()"><input type="checkbox" data-select="${r.id}" ${state.selected.has(r.id)?'checked':''}></td>${cfg.columns.map((c,i)=>`<td>${i===0?`<div class="cell-main"><strong>${value(r[c],c,cfg)}</strong><span>Updated ${fmtDate(r.updatedAt)}</span></div>`:value(r[c],c,cfg)}</td>`).join('')}<td onclick="event.stopPropagation()"><button class="icon-btn" data-row-menu="${r.id}">⋮</button></td></tr>`}
function mobile(cfg,r){return `<article class="mobile-record" data-open="${r.id}"><div class="mobile-record-head"><div><span>${esc(cfg.title)}</span><strong>${value(r[cfg.columns[0]],cfg.columns[0],cfg)}</strong></div><button class="icon-btn" data-row-menu="${r.id}">⋮</button></div><div class="mobile-record-grid">${cfg.columns.slice(1,6).map(c=>`<div class="mobile-record-field"><span>${esc(title(c))}</span><strong>${value(r[c],c,cfg)}</strong></div>`).join('')}</div></article>`}
function detail(cfg,id){const r=data(cfg).find(x=>String(x.id)===String(id));if(!r)return `<div class="empty-state"><h2>Record not found</h2></div>`;const fields=Object.entries(r).filter(([k])=>!['id','createdAt','updatedAt','status','components','lines'].includes(k));return head(cfg.title,String(r[cfg.primary]||r[cfg.columns[0]]),`Complete ${cfg.title.toLowerCase()} record with workflow and linked costing context.`,`<a class="btn btn-secondary" href="#/${cfg.route}">← Back</a>${can('edit')&&!cfg.readonly?'<button class="btn btn-primary" data-action="edit">Edit</button>':''}`)+`<div class="detail-layout"><section class="card"><div class="card-head"><div><h2>Record details</h2><p>Current status ${value(r.status||r.approvalStage||r.costStatus,'status')}</p></div></div><div class="card-body detail-grid">${fields.map(([k,v])=>`<div class="detail-field"><span>${esc(title(k))}</span><strong>${value(v,k,cfg)}</strong></div>`).join('')}</div>${workflowButtons(cfg,r)}</section><aside class="detail-side"><section class="card"><div class="card-head"><h2>Lifecycle</h2></div><div class="card-body timeline"><div><span></span><strong>Created</strong><small>${fmtDate(r.createdAt)}</small></div><div><span></span><strong>Updated</strong><small>${fmtDate(r.updatedAt)}</small></div><div><span></span><strong>Current state</strong><small>${esc(r.status||r.approvalStage||r.costStatus||'Active')}</small></div></div></section><section class="card"><div class="card-head"><h2>Controls</h2></div><div class="card-body compact-list"><button class="btn btn-secondary btn-full" data-action="duplicate">Create revision / duplicate</button>${can('archive')?'<button class="btn btn-danger btn-full" data-action="archive">Archive</button>':''}</div></section></aside></div>${linesSection(cfg,r)}`}
function linesSection(cfg,r){const lines=r.components||r.lines;if(!Array.isArray(lines))return '';const isRecipe=!!r.components;return `<section class="card"><div class="card-head"><div><h2>${isRecipe?'Recipe components':'BOM lines'}</h2><p>${lines.length} controlled lines</p></div>${can('edit')?'<button class="btn btn-primary" data-action="add-component">+ Add line</button>':''}</div><div class="table-wrap"><table><thead><tr><th>SKU</th><th>Component</th><th>Qty</th><th>UOM</th><th>${isRecipe?'Wastage':'Cost'}</th><th>Line cost</th><th></th></tr></thead><tbody>${lines.map((l,i)=>`<tr><td class="code">${esc(l.sku)}</td><td>${esc(l.name)}</td><td>${fmtNum(l.qty,3)}</td><td>${esc(l.uom)}</td><td>${isRecipe?fmtNum(l.wastagePct)+'%':fmtMoney(l.cost)}</td><td>${fmtMoney(isRecipe?l.qty*l.unitCost*(1+(l.wastagePct||0)/100):l.cost)}</td><td>${can('edit')?`<button class="icon-btn" data-edit-line="${i}">✎</button><button class="icon-btn" data-delete-line="${i}">×</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`}
function workflowButtons(cfg,r){if(!cfg.workflow)return '';const b=[];if(can('edit')&&['Draft','draft'].includes(r.status))b.push(['submit','Submit for technical review']);if(can('approve')&&String(r.approvalStage||r.status).toLowerCase().includes('technical'))b.push(['technical-approve','Approve technical']);if(can('approve')&&String(r.approvalStage||r.status).toLowerCase().includes('qa'))b.push(['qa-approve','Approve QA']);if(can('cost')&&String(r.approvalStage||r.status).toLowerCase().includes('cost'))b.push(['cost-approve','Approve cost']);if(can('release')&&['Plant Trial','Approved','Review'].includes(r.status||r.approvalStage))b.push(['release','Release']);if(cfg.workflow==='rollup'&&can('cost'))b.push(['rollup','Recalculate']);if(cfg.workflow==='simulation'&&can('cost'))b.push(['simulate','Run simulation']);if(cfg.workflow==='approval'&&can('approve')){b.push(['approve','Approve']);b.push(['reject','Return'])}return b.length?`<div class="workflow-actions">${b.map(x=>`<button class="btn ${x[0]==='reject'?'btn-danger':'btn-primary'}" data-workflow="${x[0]}">${esc(x[1])}</button>`).join('')}</div>`:''}
function modalHtml(){if(state.modal.type==='row-menu'){const cfg=R[state.route],r=data(cfg).find(x=>String(x.id)===String(state.modal.id));return `<div class="modal-backdrop" data-action="close-modal"><div class="action-sheet" onclick="event.stopPropagation()"><h3>${esc(r?.[cfg.primary]||'Actions')}</h3><button data-action="open-row" data-id="${state.modal.id}">Open details</button>${can('edit')&&!cfg.readonly?`<button data-action="edit-row" data-id="${state.modal.id}">Edit record</button>`:''}<button data-action="duplicate-row" data-id="${state.modal.id}">Create revision / duplicate</button>${can('archive')?`<button class="danger" data-action="archive-row" data-id="${state.modal.id}">Archive</button>`:''}</div></div>`}if(state.modal.type==='line'){const cfg=R[state.route],r=data(cfg).find(x=>String(x.id)===String(state.id)),lines=r?.components||r?.lines||[],l=state.modal.index!==null&&state.modal.index!==undefined?lines[state.modal.index]:{};return `<div class="modal-backdrop"><div class="modal-card"><div class="modal-head"><h2>${state.modal.index!==undefined?'Edit':'Add'} component line</h2><button class="icon-btn" data-action="close-modal">×</button></div><form id="line-form" class="form-grid"><label>SKU<input name="sku" value="${esc(l.sku||'')}"></label><label>Component<input name="name" value="${esc(l.name||'')}"></label><label>Quantity<input type="number" step="0.001" name="qty" value="${esc(l.qty||0)}"></label><label>UOM<input name="uom" value="${esc(l.uom||'KG')}"></label><label>Wastage %<input type="number" step="0.01" name="wastagePct" value="${esc(l.wastagePct||0)}"></label><label>Unit cost<input type="number" step="0.01" name="unitCost" value="${esc(l.unitCost||0)}"></label><div class="form-actions"><button type="button" class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary">Save line</button></div></form></div></div>`}const cfg=R[state.modal.route||state.route],r=state.modal.id?data(cfg).find(x=>String(x.id)===String(state.modal.id)):null,fields=cfg.columns.slice(0,10);return `<div class="modal-backdrop"><div class="modal-card"><div class="modal-head"><h2>${r?'Edit':'New'} ${esc(cfg.title.replace(/s$/,''))}</h2><button class="icon-btn" data-action="close-modal">×</button></div><form id="record-form" class="form-grid">${fields.map(f=>`<label>${esc(title(f))}<input name="${f}" value="${esc(r?.[f]??'')}" ${cfg.money.includes(f)||typeof r?.[f]==='number'?'type="number" step="0.01"':''}></label>`).join('')}<div class="form-actions"><button type="button" class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary">Save record</button></div></form></div></div>`}
function commandHtml(){const items=nav().flatMap(g=>g[1]);return `<div class="command-backdrop" data-action="close-command"><div class="command-box" onclick="event.stopPropagation()"><input id="command-input" placeholder="Search pages..." autofocus><div class="command-results">${items.map(i=>`<a class="command-item" href="#/${i[0]}"><span class="nav-icon">${i[1]}</span><div><strong>${esc(i[2])}</strong><small>Open ${esc(i[2].toLowerCase())}</small></div></a>`).join('')}</div></div></div>`}
function parse(){const p=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean),next=p[0]||'dashboard',nextId=p[1]||null,changed=next!==state.route||String(nextId)!==String(state.id);state.route=next;state.id=nextId;if(!allowed(state.route))state.route='dashboard';if(changed){state.search='';state.status='all';state.page=1;state.selected.clear()}}
