function bind(){qsa('[data-action]').forEach(el=>el.addEventListener('click',e=>{const a=el.dataset.action;if(a==='open-sidebar'){state.ui.sidebar=true;saveUi();render()}if(a==='close-sidebar'){state.ui.sidebar=false;saveUi();render()}if(a==='theme'){state.ui.theme=state.ui.theme==='dark'?'light':'dark';saveUi();render()}if(a==='logout'){localStorage.removeItem(SESSION);location.href='login-admin.html'}if(a==='command'){state.command=true;render();setTimeout(()=>byId('command-input')?.focus(),20)}if(a==='close-command'){state.command=false;render()}if(a==='notifications')toast('3 release and costing actions require attention.','info');if(a==='new'){state.modal={type:'form',route:state.route};render()}if(a==='close-modal'){state.modal=null;render()}if(a==='open-row'){state.modal=null;location.hash=`#/${state.route}/${el.dataset.id}`}if(a==='edit-row'){state.modal={type:'form',route:state.route,id:el.dataset.id};render()}if(a==='archive-row')archive(el.dataset.id);if(a==='duplicate-row'){duplicate(el.dataset.id);state.modal=null}if(a==='edit'){state.modal={type:'form',route:state.route,id:state.id};render()}if(a==='archive')archive(state.id);if(a==='duplicate')duplicate(state.id);if(a==='export-current')exportCsv();if(a==='add-component'){state.modal={type:'line',index:undefined};render()}if(a==='run-rollup'){workflow('rollup')}if(a==='approve-selected'){toast('Selected approvals processed in demo.')}}));qsa('[data-open]').forEach(el=>el.addEventListener('click',()=>location.hash=`#/${state.route}/${el.dataset.open}`));qsa('[data-row-menu]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();state.modal={type:'row-menu',id:el.dataset.rowMenu};render()}));qsa('[data-sort]').forEach(el=>el.addEventListener('click',()=>{state.dir=state.sort===el.dataset.sort&&state.dir==='asc'?'desc':'asc';state.sort=el.dataset.sort;render()}));qsa('[data-page]').forEach(el=>el.addEventListener('click',()=>{state.page=Math.max(1,Number(el.dataset.page));render()}));qsa('[data-select]').forEach(el=>el.addEventListener('change',()=>{const id=Number(el.dataset.select);el.checked?state.selected.add(id):state.selected.delete(id)}));qs('[data-action="select-all"]')?.addEventListener('change',e=>{data(R[state.route]).forEach(r=>e.target.checked?state.selected.add(r.id):state.selected.delete(r.id));render()});byId('list-search')?.addEventListener('input',e=>{state.search=e.target.value;state.page=1;clearTimeout(window.__bomSearch);window.__bomSearch=setTimeout(render,180)});byId('status-filter')?.addEventListener('change',e=>{state.status=e.target.value;state.page=1;render()});byId('record-form')?.addEventListener('submit',saveForm);byId('line-form')?.addEventListener('submit',saveLine);qsa('[data-workflow]').forEach(el=>el.addEventListener('click',()=>workflow(el.dataset.workflow)));qsa('[data-edit-line]').forEach(el=>el.addEventListener('click',()=>{state.modal={type:'line',index:Number(el.dataset.editLine)};render()}));qsa('[data-delete-line]').forEach(el=>el.addEventListener('click',()=>deleteLine(Number(el.dataset.deleteLine))));byId('batch-target')?.addEventListener('input',e=>{window.__batchSize=Number(e.target.value);clearTimeout(window.__batchTimer);window.__batchTimer=setTimeout(render,120)});byId('command-input')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();qsa('.command-item').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'flex':'none')});document.addEventListener('keydown',keyHandler,{once:true})}
function keyHandler(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.command=true;render()}else if(e.key==='Escape'&&(state.command||state.modal)){state.command=false;state.modal=null;render()}}
function saveForm(e){e.preventDefault();const cfg=R[state.modal.route||state.route],d=Object.fromEntries(new FormData(e.target).entries()),rows=state.db[cfg.key]||(state.db[cfg.key]=[]),r=state.modal.id?rows.find(x=>String(x.id)===String(state.modal.id)):null;Object.keys(d).forEach(k=>{if(cfg.money.includes(k)||typeof (r||rows[0]||{})[k]==='number')d[k]=Number(d[k]||0)});if(r){const before=JSON.stringify(r);Object.assign(r,d,{updatedAt:now()});audit('Updated '+cfg.title,String(r[cfg.primary]),before,JSON.stringify(r));toast('Record updated.')}else{const id=Math.max(0,...rows.map(x=>Number(x.id)||0))+1,n={id,createdAt:now(),updatedAt:now(),status:'draft',...d};rows.unshift(n);audit('Created '+cfg.title,String(n[cfg.primary]),'—',JSON.stringify(n));toast('Record created.')}save();state.modal=null;render()}
function saveLine(e){e.preventDefault();const cfg=R[state.route],r=data(cfg).find(x=>String(x.id)===String(state.id));if(!r)return;const lines=r.components||(r.lines||(r.components=[])),d=Object.fromEntries(new FormData(e.target).entries());['qty','wastagePct','unitCost'].forEach(k=>d[k]=Number(d[k]||0));if(state.modal.index!==undefined)lines[state.modal.index]=d;else lines.push(d);r.updatedAt=now();audit('Changed component line',r[cfg.primary]);save();state.modal=null;toast('Component line saved.');render()}
function deleteLine(i){const cfg=R[state.route],r=data(cfg).find(x=>String(x.id)===String(state.id)),lines=r?.components||r?.lines;if(!lines||!confirm('Delete this line?'))return;lines.splice(i,1);r.updatedAt=now();audit('Deleted component line',r[cfg.primary]);save();toast('Line removed.');render()}
function archive(id){const cfg=R[state.route],r=data(cfg).find(x=>String(x.id)===String(id));if(!r||!confirm(`Archive ${r[cfg.primary]}?`))return;const b=r.status;r.status=r.status==='archived'?'active':'archived';r.updatedAt=now();audit('Archive/restore',r[cfg.primary],b,r.status);save();state.modal=null;location.hash=`#/${state.route}`;render()}
