function exportCsv(){const cfg=R[state.route],rows=cfg?data(cfg):[];if(!rows.length){toast('No exportable rows.','error');return}const cols=cfg.columns,csv=[cols.join(','),...rows.map(r=>cols.map(c=>'"'+String(r[c]??'').replace(/"/g,'""')+'"').join(','))].join('\n'),blob=new Blob([csv],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`tan90-${state.route}-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(url);toast('CSV downloaded.')}
function workflow(a){const cfg=R[state.route],r=data(cfg).find(x=>String(x.id)===String(state.id));if(!r&&a!=='rollup')return;const before=r?JSON.stringify(r):'—';let msg='Workflow updated.';if(a==='submit'){r.status='Review';r.approvalStage='Technical Review';msg='Submitted for technical review.'}if(a==='technical-approve'){r.approvalStage='QA Review';msg='Technical review approved.'}if(a==='qa-approve'){r.approvalStage='Cost Review';msg='QA gate approved.'}if(a==='cost-approve'){r.approvalStage='Plant Trial';r.status='Plant Trial';msg='Cost approved; moved to plant trial.'}if(a==='release'){r.approvalStage='Released';r.status='Released';msg='Object released for production.'}if(a==='approve'){r.status='Approved';msg='Approval completed.'}if(a==='reject'){r.status='Returned';msg='Returned for correction.'}if(a==='simulate'){r.simulatedCost=Number(r.baseCost||0)*1.07;r.deltaPct=7;r.status='Saved';msg='Scenario recalculated.'}if(a==='rollup'){const id=Math.max(0,...state.db.costRollups.map(x=>x.id))+1;state.db.costRollups.unshift({id,createdAt:now(),updatedAt:now(),number:`ROLL-2026-${String(id).padStart(4,'0')}`,product:'500gm PCM Pouch - Blue',bom:'BOM-PCM500-R03',recipe:'REC-PCM500-R04',oldCost:55.9,newCost:56.62,changePct:1.29,runDate:new Date().toISOString().slice(0,10),runBy:state.session.name,status:'Completed'});audit('Ran cost roll-up','BOM-PCM500-R03');save();toast('Cost roll-up completed and saved.');render();return}r.updatedAt=now();audit(title(a),String(r[cfg.primary]),before,JSON.stringify(r));save();toast(msg);render()}
